 1	// Package orders lists orders a page at a time.
 2	package orders
 3	
 4	import (
 5		"errors"
 6		"sort"
 7	)
 8	
 9	// ErrNotFound is returned by Get when no order has the id.
10	var ErrNotFound = errors.New("orders: no such order")
11	
12	// Order is one row of the orders table.
13	type Order struct {
14		ID       int
15		Customer string
16		Total    int // cents
17		Paid     bool
18	}
19	
20	// Store holds the orders in id order.
21	type Store struct {
22		rows []Order
23	}
24	
25	// NewStore returns a store that holds rows, sorted by id.
26	func NewStore(rows []Order) *Store {
27		sorted := append([]Order(nil), rows...)
28		sort.Slice(sorted, func(i, j int) bool { return sorted[i].ID < sorted[j].ID })
29		return &Store{rows: sorted}
30	}
31	
32	// Len is the number of orders in the store.
33	func (s *Store) Len() int { return len(s.rows) }
34	
35	// Get returns the order with the id, or ErrNotFound.
36	func (s *Store) Get(id int) (Order, error) {
37		i := sort.Search(len(s.rows), func(i int) bool { return s.rows[i].ID >= id })
38		if i == len(s.rows) || s.rows[i].ID != id {
39			return Order{}, ErrNotFound
40		}
41		return s.rows[i], nil
42	}
43	
44	// Pages is how many pages of size orders the store has.
45	func (s *Store) Pages(size int) int {
46		if size < 1 {
47			return 0
48		}
49		return (len(s.rows) + size - 1) / size
50	}
51	
52	// List returns the orders on one page. Pages count from 1; a page past the
53	// end, or a page or size below 1, is empty.
54	func (s *Store) List(page, size int) []Order {
55		if page < 1 || size < 1 {
56			return nil
57		}
58		offset := page * size
59		if offset >= len(s.rows) {
60			return nil
61		}
62		end := offset + size
63		if end > len(s.rows) {
64			end = len(s.rows)
65		}
66		return s.rows[offset:end]
67	}
68	
69	// Unpaid returns the orders that have not been paid, in id order.
70	func (s *Store) Unpaid() []Order {
71		var out []Order
72		for _, o := range s.rows {
73			if !o.Paid {
74				out = append(out, o)
75			}
76		}
77		return out
78	}
79	
80	// Revenue is the sum of the paid orders, in cents.
81	func (s *Store) Revenue() int {
82		total := 0
83		for _, o := range s.rows {
84			if o.Paid {
85				total += o.Total
86			}
87		}
88		return total
89	}

