 1	package orders
 2	
 3	import "testing"
 4	
 5	var sample = []Order{
 6		{1, "ada", 1200, true}, {2, "grace", 250, false}, {3, "edsger", 7500, true},
 7		{4, "barbara", 900, true}, {5, "donald", 4000, false},
 8	}
 9	
10	func ids(os []Order) []int {
11		var out []int
12		for _, o := range os {
13			out = append(out, o.ID)
14		}
15		return out
16	}
17	
18	func TestGet(t *testing.T) {
19		s := NewStore(sample)
20		o, err := s.Get(3)
21		if err != nil || o.Customer != "edsger" {
22			t.Fatalf("Get(3) = %v, %v", o, err)
23		}
24		if _, err := s.Get(9); err != ErrNotFound {
25			t.Fatalf("Get(9) error = %v, want ErrNotFound", err)
26		}
27	}
28	
29	func TestListFirstPage(t *testing.T) {
30		got := NewStore(sample).List(1, 2)
31		if len(got) != 2 || got[0].ID != 1 || got[1].ID != 2 {
32			t.Errorf("List(1, 2) holds orders %v, want 1 and 2", ids(got))
33		}
34	}
35	
36	func TestListLastPage(t *testing.T) {
37		got := NewStore(sample).List(3, 2)
38		if len(got) != 1 || got[0].ID != 5 {
39			t.Errorf("List(3, 2) holds orders %v, want 5", ids(got))
40		}
41	}
42	
43	func TestPages(t *testing.T) {
44		if n := NewStore(sample).Pages(2); n != 3 {
45			t.Errorf("Pages(2) = %d, want 3", n)
46		}
47	}
48	
49	func TestRevenue(t *testing.T) {
50		if got := NewStore(sample).Revenue(); got != 9600 {
51			t.Errorf("Revenue() = %d, want 9600", got)
52		}
53	}

